-- ALTER MATERIALIZED VIEW. https://docs.databricks.com/aws/en/sql/language-manual/sql-ref-syntax-ddl-alter-materialized-view
ALTER MATERIALIZED VIEW v SET OWNER TO `u`;

ALTER MATERIALIZED VIEW v DROP SCHEDULE;

ALTER MATERIALIZED VIEW v ADD TRIGGER ON UPDATE;

ALTER MATERIALIZED VIEW v ALTER SCHEDULE EVERY 2 HOURS;

ALTER MATERIALIZED VIEW v ALTER SCHEDULE CRON '0 0 * * *' AT TIME ZONE 'UTC';

ALTER MATERIALIZED VIEW v ADD SCHEDULE REFRESH EVERY 1 DAY;

ALTER MATERIALIZED VIEW v ALTER COLUMN c COMMENT 'x';
